#!/usr/bin/env python3
import sys, os, re, json, math, functools, inspect
from collections import OrderedDict

VERSION = "39.2.0"
HELP = """
  fx 39.2.0
    Terminal JSON viewer

  Usage
    fx data.json
    fx data.json .field
    curl ... | fx

  Flags
    -h, --help            print help
    -v, --version         print version
    --themes              print themes
    --comp <shell>        print completion script
    -r, --raw             treat input as a raw string
    -s, --slurp           read all inputs into an array
    --yaml                parse input as YAML
    --toml                parse input as TOML
    --strict              strict mode
    --no-inline           disable inlining in output
    --game-of-life        play the game of life

  More info
    https://fx.wtf

  Author
    Anton Medvedev <anton@medv.io>
"""

class UndefinedType:
    def __repr__(self): return 'undefined'
    def __str__(self): return 'undefined'
    def __bool__(self): return False
    def __eq__(self, other): return other is None or other is UNDEFINED or (isinstance(other, J) and other.v is UNDEFINED)
    def __getattr__(self, name): raise JSTypeError(f"TypeError: Cannot read property '{name}' of undefined")
    def __getitem__(self, key): raise JSTypeError("TypeError: Cannot read property of undefined")
UNDEFINED = UndefinedType()

class JSTypeError(Exception): pass

def unwrap(x):
    if isinstance(x, J): return unwrap(x.v)
    if isinstance(x, UndefinedType): return UNDEFINED
    if callable(x): return x
    if isinstance(x, list): return [unwrap(i) for i in x]
    if isinstance(x, dict): return {str(k): unwrap(v) for k,v in x.items()}
    return x

def wrap(x):
    if isinstance(x, J): return x
    if isinstance(x, UndefinedType): return x
    return J(x)

def js_truthy(v):
    v = unwrap(v)
    if v is UNDEFINED or v is None or v is False: return False
    if isinstance(v, (int,float)) and (v == 0 or math.isnan(v) if isinstance(v,float) else v == 0): return False
    if isinstance(v, str) and v == '': return False
    return True

def js_str(v):
    v = unwrap(v)
    if v is UNDEFINED: return 'undefined'
    if v is None: return 'null'
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v, float):
        if math.isnan(v): return 'NaN'
        if math.isinf(v): return 'Infinity' if v > 0 else '-Infinity'
        if v.is_integer(): return str(int(v))
    if isinstance(v, list): return ','.join(js_str(i) for i in v)
    if isinstance(v, dict): return '[object Object]'
    return str(v)

class J:
    def __init__(self, v): self.v = v
    def __repr__(self): return f"J({self.v!r})"
    def __bool__(self): return js_truthy(self.v)
    def valueOf(self): return wrap(self.v)
    def toString(self): return js_str(self.v)
    def toJSON(self): return self.v

    def _num(self):
        v = unwrap(self.v)
        if v is None: return 0
        if v is True: return 1
        if v is False: return 0
        try: return float(v)
        except Exception: return float('nan')

    def __eq__(self, other):
        a, b = unwrap(self), unwrap(other)
        if (a is UNDEFINED and b is None) or (b is UNDEFINED and a is None): return True
        if a is UNDEFINED and b is UNDEFINED: return True
        return a == b
    def __ne__(self, other): return not self.__eq__(other)
    def __lt__(self, other): return self._num() < wrap(other)._num()
    def __le__(self, other): return self._num() <= wrap(other)._num()
    def __gt__(self, other): return self._num() > wrap(other)._num()
    def __ge__(self, other): return self._num() >= wrap(other)._num()

    def __add__(self, other):
        a, b = unwrap(self), unwrap(other)
        if isinstance(a, str) or isinstance(b, str) or isinstance(a, list) or isinstance(b, list) or isinstance(a, dict) or isinstance(b, dict):
            return js_str(a) + js_str(b)
        if a is UNDEFINED or b is UNDEFINED: return float('nan')
        if a is None: a = 0
        if b is None: b = 0
        return a + b
    def __radd__(self, other): return wrap(other).__add__(self)
    def __sub__(self, other): return self._num() - wrap(other)._num()
    def __rsub__(self, other): return wrap(other)._num() - self._num()
    def __mul__(self, other): return self._num() * wrap(other)._num()
    def __rmul__(self, other): return wrap(other)._num() * self._num()
    def __truediv__(self, other):
        a, b = self._num(), wrap(other)._num()
        if b == 0:
            if a == 0 or math.isnan(a): return float('nan')
            return math.copysign(float('inf'), a)
        return a / b
    def __rtruediv__(self, other): return wrap(other).__truediv__(self)
    def __mod__(self, other): return self._num() % wrap(other)._num()
    def __neg__(self): return -self._num()

    def __getitem__(self, key):
        v = unwrap(self.v)
        key = unwrap(key)
        if v is UNDEFINED: raise JSTypeError("TypeError: Cannot read property of undefined")
        if v is None: raise JSTypeError("TypeError: Cannot read property of undefined")
        try:
            if isinstance(v, dict): return wrap(v.get(str(key), UNDEFINED))
            if isinstance(v, (list, str)):
                i = int(key)
                if i < 0: i += len(v)
                if 0 <= i < len(v): return wrap(v[i])
                return UNDEFINED
        except Exception:
            return UNDEFINED
        return UNDEFINED

    def __getattr__(self, name):
        v = unwrap(self.v)
        if name == 'length':
            if isinstance(v, (list, dict, str)): return len(v)
            return UNDEFINED
        if name == 'map': return self.map
        if name == 'filter': return self.filter
        if name == 'reduce': return self.reduce
        if name == 'sort': return self.sort
        if name == 'reverse': return self.reverse
        if name == 'includes': return self.includes
        if name == 'indexOf': return self.indexOf
        if name == 'join': return self.join
        if name == 'slice': return self.slice
        if name == 'find': return self.find
        if name == 'some': return self.some
        if name == 'every': return self.every
        if name == 'flat': return self.flat
        if name == 'trim': return self.trim
        if name == 'split': return self.split
        if name == 'replace': return self.replace
        if name == 'startsWith': return self.startsWith
        if name == 'endsWith': return self.endsWith
        if name == 'toUpperCase': return self.toUpperCase
        if name == 'toLowerCase': return self.toLowerCase
        if name == 'hasOwnProperty': return self.hasOwnProperty
        if v is UNDEFINED: raise JSTypeError(f"TypeError: Cannot read property '{name}' of undefined")
        if v is None: raise JSTypeError(f"TypeError: Cannot read property '{name}' of undefined")
        if isinstance(v, dict): return wrap(v.get(name, UNDEFINED))
        return UNDEFINED

    def _arr(self):
        v = unwrap(self.v)
        if isinstance(v, list): return v
        if isinstance(v, dict): return list(v.values())
        if isinstance(v, str): return list(v)
        raise JSTypeError(f"TypeError: {js_str(v)} is not iterable")

    def map(self, fn): return wrap([unwrap(call_js(fn, wrap(e), i, wrap(self.v))) for i,e in enumerate(self._arr())])
    def filter(self, fn): return wrap([e for i,e in enumerate(self._arr()) if js_truthy(call_js(fn, wrap(e), i, wrap(self.v)))])
    def reduce(self, fn, init=UNDEFINED):
        arr = self._arr()
        if init is UNDEFINED:
            if not arr: return UNDEFINED
            acc = wrap(arr[0]); start = 1
        else:
            acc = wrap(init); start = 0
        for i in range(start, len(arr)):
            acc = wrap(call_js(fn, acc, wrap(arr[i]), i, wrap(self.v)))
        return acc
    def sort(self, cmp=None):
        arr = list(self._arr())
        if cmp is None:
            arr.sort(key=lambda e: js_str(e))
        else:
            def c(a,b):
                r = unwrap(call_js(cmp, wrap(a), wrap(b)))
                try: return int(r)
                except Exception: return 0
            arr.sort(key=functools.cmp_to_key(c))
        return wrap(arr)
    def reverse(self): return wrap(list(reversed(self._arr())))
    def includes(self, val): return any(wrap(e) == val for e in self._arr())
    def indexOf(self, val):
        for i,e in enumerate(self._arr()):
            if wrap(e) == val: return i
        return -1
    def join(self, sep=','):
        sep = js_str(sep)
        return sep.join(js_str(e) for e in self._arr())
    def slice(self, start=None, end=None):
        arr = self._arr() if not isinstance(unwrap(self.v), str) else unwrap(self.v)
        s = None if start is None else int(unwrap(start))
        e = None if end is None else int(unwrap(end))
        return wrap(arr[s:e])
    def find(self, fn):
        for i,e in enumerate(self._arr()):
            if js_truthy(call_js(fn, wrap(e), i, wrap(self.v))): return wrap(e)
        return UNDEFINED
    def some(self, fn): return any(js_truthy(call_js(fn, wrap(e), i, wrap(self.v))) for i,e in enumerate(self._arr()))
    def every(self, fn): return all(js_truthy(call_js(fn, wrap(e), i, wrap(self.v))) for i,e in enumerate(self._arr()))
    def flat(self, depth=1):
        def fl(a, d):
            out=[]
            for e in a:
                if d>0 and isinstance(e, list): out.extend(fl(e,d-1))
                else: out.append(e)
            return out
        return wrap(fl(self._arr(), int(unwrap(depth))))
    def trim(self): return js_str(self.v).strip()
    def split(self, sep=None): return wrap(js_str(self.v).split(None if sep is None else js_str(sep)))
    def replace(self, a, b): return js_str(self.v).replace(js_str(a), js_str(b), 1)
    def startsWith(self, s): return js_str(self.v).startswith(js_str(s))
    def endsWith(self, s): return js_str(self.v).endswith(js_str(s))
    def toUpperCase(self): return js_str(self.v).upper()
    def toLowerCase(self): return js_str(self.v).lower()
    def hasOwnProperty(self, k):
        v=unwrap(self.v); return isinstance(v, dict) and str(unwrap(k)) in v


def call_js(fn, *args):
    if isinstance(fn, J): fn = unwrap(fn)
    if not callable(fn): raise JSTypeError(f"TypeError: Not a function: {js_str(fn)}")
    for n in range(len(args), -1, -1):
        try: return fn(*args[:n])
        except TypeError as e:
            if n == 0: raise
            continue

# Helper functions observed in fx.
def len_(v):
    v=unwrap(v)
    if isinstance(v,(list,dict,str)): return len(v)
    if v is UNDEFINED or v is None: return 0
    return 0

def keys(v):
    v=unwrap(v)
    if isinstance(v, dict): return list(v.keys())
    if isinstance(v, list): return [str(i) for i in range(len(v))]
    return []

def values(v):
    v=unwrap(v)
    if isinstance(v, dict): return list(v.values())
    if isinstance(v, list): return v
    return []

def sort(v): return wrap(v).sort()
def reverse(v): return wrap(v).reverse()
def uniq(v):
    arr = wrap(v)._arr(); out=[]; seen=set()
    for e in arr:
        if isinstance(e,(dict,list)):
            out.append(e)  # JS Set keeps distinct object references; JSON inputs are distinct.
        else:
            key = (type(e).__name__, e)
            if key not in seen: seen.add(key); out.append(e)
    return wrap(out)
def map_(v, fn): return wrap(v).map(fn)
def filter_(v, fn): return wrap(v).filter(fn)
def sortBy_(v, fn):
    arr=list(wrap(v)._arr())
    arr.sort(key=lambda e: sort_key(unwrap(call_js(fn, wrap(e)))))
    return wrap(arr)
def groupBy_(v, fn):
    out=OrderedDict()
    for e in wrap(v)._arr():
        k=js_str(call_js(fn, wrap(e)))
        out.setdefault(k, []).append(e)
    return wrap(out)
def sort_key(x):
    if isinstance(x,(int,float,str)): return x
    return js_str(x)

def optional(obj, name):
    obj=wrap(obj); v=unwrap(obj)
    if v is None or v is UNDEFINED: return UNDEFINED
    return getattr(obj, name)

def nullish(a,b):
    av=unwrap(a)
    return b if av is None or av is UNDEFINED else a

class ObjectNS:
    @staticmethod
    def keys(v): return wrap(keys(v))
    @staticmethod
    def values(v): return wrap(values(v))
    @staticmethod
    def entries(v):
        v=unwrap(v)
        if isinstance(v, dict): return wrap([[k,val] for k,val in v.items()])
        if isinstance(v, list): return wrap([[str(i),val] for i,val in enumerate(v)])
        return wrap([])
    @staticmethod
    def fromEntries(v): return wrap({str(unwrap(k)): unwrap(val) for k,val in unwrap(v)})

class JSONNS:
    @staticmethod
    def stringify(v): return json.dumps(clean_for_json(unwrap(v)), ensure_ascii=False, separators=(',',':'), allow_nan=True)
    @staticmethod
    def parse(s): return wrap(json.loads(js_str(s)))

class MathNS:
    PI=math.pi; E=math.e
    @staticmethod
    def round(x): return int(math.floor(float(unwrap(x))+0.5))
    @staticmethod
    def floor(x): return math.floor(float(unwrap(x)))
    @staticmethod
    def ceil(x): return math.ceil(float(unwrap(x)))
    @staticmethod
    def abs(x): return abs(float(unwrap(x)))
    @staticmethod
    def max(*xs): return max(float(unwrap(x)) for x in xs)
    @staticmethod
    def min(*xs): return min(float(unwrap(x)) for x in xs)
    @staticmethod
    def random(): return 0.5

# Parsing / translation

def convert_template(s):
    s=s.strip()
    if len(s)>=2 and s[0]=='`' and s[-1]=='`':
        body=s[1:-1]
        parts=[]; last=0
        for m in re.finditer(r'\$\{([^}]*)\}', body):
            if m.start()>last: parts.append(repr(body[last:m.start()]))
            parts.append(f"js_str({translate(m.group(1))})")
            last=m.end()
        if last<len(body): parts.append(repr(body[last:]))
        return ' + '.join(parts) if parts else "''"
    return s

def replace_optional(s):
    pat=re.compile(r'([A-Za-z_][\w]*(?:\.[A-Za-z_][\w]*|\[[^\]]+\])*)\?\.([A-Za-z_][\w]*)')
    while True:
        ns=pat.sub(r"optional(\1, '\2')", s)
        if ns==s: return s
        s=ns

def find_matching_left(s, pos):
    i=pos-1
    while i>=0 and s[i].isspace(): i-=1
    if i>=0 and s[i]==')':
        depth=1; j=i-1
        while j>=0:
            if s[j]==')': depth+=1
            elif s[j]=='(':
                depth-=1
                if depth==0: return j, i+1, s[j+1:i]
            j-=1
    j=i
    while j>=0 and (s[j].isalnum() or s[j] in '_$'):
        j-=1
    return j+1, i+1, s[j+1:i+1]

def find_body_end(s, start):
    i=start; depth=0; quote=None; esc=False
    while i<len(s):
        c=s[i]
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in '"\'`': quote=c
            elif c in '([{': depth+=1
            elif c in ')]}':
                if depth==0: break
                depth-=1
            elif c==',' and depth==0: break
        i+=1
    return i

def replace_arrows(s):
    while '=>' in s:
        pos=s.find('=>')
        ls, le, params=find_matching_left(s,pos)
        bs=pos+2
        while bs<len(s) and s[bs].isspace(): bs+=1
        be=find_body_end(s,bs)
        body=s[bs:be].strip()
        params=params.strip()
        if params.startswith('(') and params.endswith(')'): params=params[1:-1]
        body=body.strip()
        repl=f"(lambda {params}: {body})"
        s=s[:ls]+repl+s[be:]
    return s

def quote_object_keys(s):
    out=[]; i=0; quote=None; esc=False
    while i<len(s):
        c=s[i]
        if quote:
            out.append(c)
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
            i+=1; continue
        if c in '"\'`': quote=c; out.append(c); i+=1; continue
        if c=='{' or c==',':
            out.append(c); i+=1
            # copy whitespace
            j=i
            while j<len(s) and s[j].isspace(): out.append(s[j]); j+=1
            m=re.match(r'([A-Za-z_$][\w$]*)\s*:', s[j:])
            if m:
                key=m.group(1); out.append(repr(key)); out.append(':'); i=j+m.end()
            else:
                i=j
            continue
        out.append(c); i+=1
    return ''.join(out)

def split_top(s, op):
    depth=0; quote=None; esc=False; i=0
    while i < len(s):
        c=s[i]
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in '"\'`': quote=c
            elif c in '([{': depth+=1
            elif c in ')]}': depth-=1
            elif depth==0 and s.startswith(op,i): return s[:i], s[i+len(op):]
        i+=1
    return None

def transform_ternary(s):
    depth=0; quote=None; esc=False; qpos=-1
    for i,c in enumerate(s):
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in '"\'`': quote=c
            elif c in '([{': depth+=1
            elif c in ')]}': depth-=1
            elif c=='?' and depth==0: qpos=i; break
    if qpos<0: return s
    depth=0; quote=None; esc=False
    for j in range(qpos+1,len(s)):
        c=s[j]
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in '"\'`': quote=c
            elif c in '([{': depth+=1
            elif c in ')]}': depth-=1
            elif c==':' and depth==0:
                cond=s[:qpos]; a=s[qpos+1:j]; b=s[j+1:]
                return f"({transform_ternary(a.strip())} if js_truthy({transform_ternary(cond.strip())}) else {transform_ternary(b.strip())})"
    return s

def translate(expr):
    e=expr.strip()
    if e == '.': return 'x'
    if e.startswith('.'):
        e='x'+e
    e=convert_template(e)
    if e.startswith('`'):
        return e
    e=replace_optional(e)
    e=replace_arrows(e)
    e=quote_object_keys(e)
    e=transform_ternary(e)
    # simple nullish at top level
    sp=split_top(e,'??')
    if sp: e=f"nullish({translate(sp[0])}, {translate(sp[1])})"
    e=e.replace('===','==').replace('!==','!=')
    e=re.sub(r'(?<![=!<>])!(?!=)', ' not ', e)
    e=e.replace('&&',' and ').replace('||',' or ')
    e=re.sub(r'\btrue\b','True',e)
    e=re.sub(r'\bfalse\b','False',e)
    e=re.sub(r'\bnull\b','None',e)
    e=re.sub(r'\bundefined\b','UNDEFINED',e)
    e=re.sub(r'\bthis\b','x',e)
    # common zero division constants
    e=re.sub(r'\b0\s*/\s*0\b','NaN',e)
    e=re.sub(r'\b([1-9][0-9]*(?:\.[0-9]+)?)\s*/\s*0\b','Infinity',e)
    # helper calls that take current input as implicit first arg
    m=re.match(r'^(map|filter|sortBy|groupBy)\s*\((.*)\)$', e)
    if m:
        name,args=m.group(1),m.group(2)
        return {'map':'map_','filter':'filter_','sortBy':'sortBy_','groupBy':'groupBy_'}[name] + f"(x, {args})"
    return e

BARE_HELPERS={'len':'len_(x)','keys':'wrap(keys(x))','values':'wrap(values(x))','sort':'sort(x)','reverse':'reverse(x)','uniq':'uniq(x)'}

def eval_expr(expr, value):
    expr=expr.strip()
    if expr in BARE_HELPERS:
        code=BARE_HELPERS[expr]
    elif '=>' in expr and re.match(r'^\s*\(?\s*[A-Za-z_$][\w$]*(?:\s*,\s*[A-Za-z_$][\w$]*)*\s*\)?\s*=>', expr):
        fn=eval(translate(expr), env(wrap(value)))
        return wrap(call_js(fn, wrap(value)))
    else:
        code=translate(expr)
    return wrap(eval(code, env(wrap(value))))

def env(x):
    return {
        '__builtins__': {}, 'x': x, 'UNDEFINED': UNDEFINED, 'NaN': float('nan'), 'Infinity': float('inf'),
        'len_': len_, 'len': len_, 'keys': keys, 'values': values, 'sort': sort, 'reverse': reverse, 'uniq': uniq,
        'map_': map_, 'filter_': filter_, 'sortBy_': sortBy_, 'groupBy_': groupBy_,
        'Object': ObjectNS, 'JSON': JSONNS, 'Math': MathNS, 'wrap': wrap, 'js_truthy': js_truthy,
        'js_str': js_str, 'optional': optional, 'nullish': nullish,
        'True': True, 'False': False, 'None': None,
    }

# Input parsing

def strip_json_comments(s):
    out=[]; i=0; quote=None; esc=False
    while i<len(s):
        c=s[i]
        if quote:
            out.append(c)
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
            i+=1
        else:
