    if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
        return s[1:-1]
    try:
        if re.match(r'^-?\d+$',s): return int(s)
        if re.match(r'^-?\d+\.\d+',s): return float(s)
