        if math.isinf(v): return 'Infinity' if v>0 else '-Infinity'
        if v.is_integer(): return str(int(v))
    return str(v)

def is_scalar(v):
    v=unwrap(v); return not isinstance(v,(list,dict,OrderedDict))

def inline(v):
    v=unwrap(v)
    if isinstance(v, list): return '[ ' + ', '.join(format_value(e,0,False,False,'list_inline') for e in v) + ' ]'
    if isinstance(v, (dict,OrderedDict)): return '{ ' + ', '.join(json.dumps(str(k),ensure_ascii=False)+': '+format_value(val,0,False,False,'dict_inline') for k,val in v.items()) + ' }'
