def parse_args(argv):
    opts={'raw':False,'slurp':False,'yaml':False,'toml':False,'strict':False,'no_inline':False}
    codes=[]; i=0
    while i<len(argv):
        a=argv[i]
        if a in ('-h','--help'):
            sys.stdout.write(HELP); sys.exit(0)
        if a in ('-v','--version'):
            print(VERSION); sys.exit(0)
        if a=='--themes': print_themes(); sys.exit(0)
        if a.startswith('--comp='):
            completion(a.split('=',1)[1]); sys.exit(0)
        if a=='--comp':
            if i+1>=len(argv):
                sys.stderr.write('flag needs an argument: -comp\nUsage of ./executable:\n  -comp string\n    \t\n'); sys.exit(2)
            completion(argv[i+1]); sys.exit(0)
        if a in ('-r','--raw'): opts['raw']=True; i+=1; continue
        if a in ('-s','--slurp'): opts['slurp']=True; i+=1; continue
        # combined short flags like -sr
        if a.startswith('-') and not a.startswith('--') and len(a)>2:
            ok=True
            for ch in a[1:]:
                if ch=='s': opts['slurp']=True
                elif ch=='r': opts['raw']=True
                elif ch=='v': print(VERSION); sys.exit(0)
                elif ch=='h': sys.stdout.write(HELP); sys.exit(0)
                else: ok=False
            if ok: i+=1; continue
        if a=='--yaml': opts['yaml']=True; i+=1; continue
        if a=='--toml': opts['toml']=True; i+=1; continue
        if a=='--strict': opts['strict']=True; i+=1; continue
        if a=='--no-inline': opts['no_inline']=True; i+=1; continue
        if a=='--game-of-life': sys.exit(0)
        # Unknown flags in observed noninteractive mode are inert; keep non-flags as code.
        if a.startswith('-') and a not in ('-',):
            i+=1; continue
        codes.append(a); i+=1
    return opts,codes

