        k=js_str(call_js(fn, wrap(e)))
        out.setdefault(k, []).append(e)
    return wrap(out)
def sort_key(x):
    if isinstance(x,(int,float,str)): return x
    return js_str(x)

def optional(obj, name):
    obj=wrap(obj); v=unwrap(obj)
    if v is None or v is UNDEFINED: return UNDEFINED
    return getattr(obj, name)

def nullish(a,b):
    av=unwrap(a)
    return b if av is None or av is UNDEFINED else a

class ObjectNS:
    @staticmethod
    def keys(v): return wrap(keys(v))
    @staticmethod
    def values(v): return wrap(values(v))
    @staticmethod
    def entries(v):
        v=unwrap(v)
        if isinstance(v, dict): return wrap([[k,val] for k,val in v.items()])
        if isinstance(v, list): return wrap([[str(i),val] for i,val in enumerate(v)])
        return wrap([])
    @staticmethod
    def fromEntries(v): return wrap({str(unwrap(k)): unwrap(val) for k,val in unwrap(v)})

class JSONNS:
    @staticmethod
    def stringify(v): return json.dumps(clean_for_json(unwrap(v)), ensure_ascii=False, separators=(',',':'), allow_nan=True)
    @staticmethod
    def parse(s): return wrap(json.loads(js_str(s)))

class MathNS:
    PI=math.pi; E=math.e
    @staticmethod
    def round(x): return int(math.floor(float(unwrap(x))+0.5))
    @staticmethod
    def floor(x): return math.floor(float(unwrap(x)))
    @staticmethod
    def ceil(x): return math.ceil(float(unwrap(x)))
    @staticmethod
    def abs(x): return abs(float(unwrap(x)))
    @staticmethod
    def max(*xs): return max(float(unwrap(x)) for x in xs)
    @staticmethod
    def min(*xs): return min(float(unwrap(x)) for x in xs)
    @staticmethod
    def random(): return 0.5

# Parsing / translation

def convert_template(s):
    s=s.strip()
    if len(s)>=2 and s[0]=='`' and s[-1]=='`':
        body=s[1:-1]
        parts=[]; last=0
        for m in re.finditer(r'\$\{([^}]*)\}', body):
            if m.start()>last: parts.append(repr(body[last:m.start()]))
            parts.append(f"js_str({translate(m.group(1))})")
            last=m.end()
        if last<len(body): parts.append(repr(body[last:]))
        return ' + '.join(parts) if parts else "''"
    return s

def replace_optional(s):
    pat=re.compile(r'([A-Za-z_][\w]*(?:\.[A-Za-z_][\w]*|\[[^\]]+\])*)\?\.([A-Za-z_][\w]*)')
    while True:
        ns=pat.sub(r"optional(\1, '\2')", s)
        if ns==s: return s
        s=ns

def find_matching_left(s, pos):
    i=pos-1
    while i>=0 and s[i].isspace(): i-=1
    if i>=0 and s[i]==')':
        depth=1; j=i-1
        while j>=0:
            if s[j]==')': depth+=1
            elif s[j]=='(':
                depth-=1
                if depth==0: return j, i+1, s[j+1:i]
            j-=1
    j=i
    while j>=0 and (s[j].isalnum() or s[j] in '_$'):
        j-=1
    return j+1, i+1, s[j+1:i+1]

def find_body_end(s, start):
    i=start; depth=0; quote=None; esc=False
    while i<len(s):
        c=s[i]
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in '"\'`': quote=c
            elif c in '([{': depth+=1
            elif c in ')]}':
                if depth==0: break
                depth-=1
            elif c==',' and depth==0: break
        i+=1
    return i

def replace_arrows(s):
    while '=>' in s:
        pos=s.find('=>')
        ls, le, params=find_matching_left(s,pos)
        bs=pos+2
        while bs<len(s) and s[bs].isspace(): bs+=1
        be=find_body_end(s,bs)
        body=s[bs:be].strip()
        params=params.strip()
        if params.startswith('(') and params.endswith(')'): params=params[1:-1]
        body=body.strip()
        repl=f"(lambda {params}: {body})"
        s=s[:ls]+repl+s[be:]
    return s

def quote_object_keys(s):
    out=[]; i=0; quote=None; esc=False
    while i<len(s):
        c=s[i]
        if quote:
            out.append(c)
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
            i+=1; continue
        if c in '"\'`': quote=c; out.append(c); i+=1; continue
        if c=='{' or c==',':
            out.append(c); i+=1
            # copy whitespace
            j=i
            while j<len(s) and s[j].isspace(): out.append(s[j]); j+=1
            m=re.match(r'([A-Za-z_$][\w$]*)\s*:', s[j:])
            if m:
                key=m.group(1); out.append(repr(key)); out.append(':'); i=j+m.end()
            else:
                i=j
            continue
        out.append(c); i+=1
    return ''.join(out)

def split_top(s, op):
    depth=0; quote=None; esc=False; i=0
    while i < len(s):
        c=s[i]
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in '"\'`': quote=c
            elif c in '([{': depth+=1
            elif c in ')]}': depth-=1
            elif depth==0 and s.startswith(op,i): return s[:i], s[i+len(op):]
        i+=1
    return None

def transform_ternary(s):
    depth=0; quote=None; esc=False; qpos=-1
    for i,c in enumerate(s):
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in '"\'`': quote=c
            elif c in '([{': depth+=1
            elif c in ')]}': depth-=1
            elif c=='?' and depth==0: qpos=i; break
    if qpos<0: return s
    depth=0; quote=None; esc=False
    for j in range(qpos+1,len(s)):
        c=s[j]
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in '"\'`': quote=c
            elif c in '([{': depth+=1
            elif c in ')]}': depth-=1
            elif c==':' and depth==0:
                cond=s[:qpos]; a=s[qpos+1:j]; b=s[j+1:]
                return f"({transform_ternary(a.strip())} if js_truthy({transform_ternary(cond.strip())}) else {transform_ternary(b.strip())})"
    return s

def translate(expr):
    e=expr.strip()
    if e == '.': return 'x'
    if e.startswith('.'):
        e='x'+e
    e=convert_template(e)
    if e.startswith('`'):
        return e
    e=replace_optional(e)
    e=replace_arrows(e)
    e=quote_object_keys(e)
    e=transform_ternary(e)
    # simple nullish at top level
    sp=split_top(e,'??')
    if sp: e=f"nullish({translate(sp[0])}, {translate(sp[1])})"
    e=e.replace('===','==').replace('!==','!=')
    e=re.sub(r'(?<![=!<>])!(?!=)', ' not ', e)
    e=e.replace('&&',' and ').replace('||',' or ')
    e=re.sub(r'\btrue\b','True',e)
    e=re.sub(r'\bfalse\b','False',e)
    e=re.sub(r'\bnull\b','None',e)
    e=re.sub(r'\bundefined\b','UNDEFINED',e)
    e=re.sub(r'\bthis\b','x',e)
    # common zero division constants
    e=re.sub(r'\b0\s*/\s*0\b','NaN',e)
    e=re.sub(r'\b([1-9][0-9]*(?:\.[0-9]+)?)\s*/\s*0\b','Infinity',e)
    # helper calls that take current input as implicit first arg
    m=re.match(r'^(map|filter|sortBy|groupBy)\s*\((.*)\)$', e)
    if m:
        name,args=m.group(1),m.group(2)
        return {'map':'map_','filter':'filter_','sortBy':'sortBy_','groupBy':'groupBy_'}[name] + f"(x, {args})"
    return e

BARE_HELPERS={'len':'len_(x)','keys':'wrap(keys(x))','values':'wrap(values(x))','sort':'sort(x)','reverse':'reverse(x)','uniq':'uniq(x)'}

def eval_expr(expr, value):
    expr=expr.strip()
    if expr in BARE_HELPERS:
        code=BARE_HELPERS[expr]
    elif '=>' in expr and re.match(r'^\s*\(?\s*[A-Za-z_$][\w$]*(?:\s*,\s*[A-Za-z_$][\w$]*)*\s*\)?\s*=>', expr):
        fn=eval(translate(expr), env(wrap(value)))
        return wrap(call_js(fn, wrap(value)))
    else:
        code=translate(expr)
    return wrap(eval(code, env(wrap(value))))

def env(x):
    return {
        '__builtins__': {}, 'x': x, 'UNDEFINED': UNDEFINED, 'NaN': float('nan'), 'Infinity': float('inf'),
        'len_': len_, 'len': len_, 'keys': keys, 'values': values, 'sort': sort, 'reverse': reverse, 'uniq': uniq,
        'map_': map_, 'filter_': filter_, 'sortBy_': sortBy_, 'groupBy_': groupBy_,
        'Object': ObjectNS, 'JSON': JSONNS, 'Math': MathNS, 'wrap': wrap, 'js_truthy': js_truthy,
        'js_str': js_str, 'optional': optional, 'nullish': nullish,
        'True': True, 'False': False, 'None': None,
    }

# Input parsing

def strip_json_comments(s):
    out=[]; i=0; quote=None; esc=False
    while i<len(s):
        c=s[i]
        if quote:
            out.append(c)
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
            i+=1
        else:
            if c in '"': quote=c; out.append(c); i+=1
            elif c=='/' and i+1<len(s) and s[i+1]=='/':
                while i<len(s) and s[i]!='\n': i+=1
            else:
                out.append(c); i+=1
    return ''.join(out)

def clean_json_text(s, strict=False):
    if not strict: s=strip_json_comments(s)
    if not strict: s=re.sub(r',\s*([}\]])', r'\1', s)
    return s

def parse_json_values(s, strict=False):
    s=clean_json_text(s, strict)
    vals=[]; dec=json.JSONDecoder(object_pairs_hook=OrderedDict); i=0
    while True:
        while i<len(s) and s[i].isspace(): i+=1
        if i>=len(s): break
        try:
            v,j=dec.raw_decode(s,i)
        except Exception as e:
            raise ValueError(str(e))
        vals.append(v); i=j
    return vals

def parse_scalar(s):
    s=s.strip()
    if s=='': return ''
    if s in ('true','True'): return True
    if s in ('false','False'): return False
    if s in ('null','Null','~'): return None
    if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
        return s[1:-1]
    try:
        if re.match(r'^-?\d+$',s): return int(s)
        if re.match(r'^-?\d+\.\d+',s): return float(s)
    except Exception: pass
    return s

def parse_yaml(s):
    lines=[ln.rstrip() for ln in s.splitlines() if ln.strip() and not ln.lstrip().startswith('#')]
    root=OrderedDict(); i=0
    while i<len(lines):
        line=lines[i]
        if ':' in line and not line.lstrip().startswith('-'):
            key,rest=line.split(':',1); key=key.strip(); rest=rest.strip()
            if rest:
                root[key]=parse_scalar(rest); i+=1
            else:
                arr=[]; obj=OrderedDict(); i+=1
                while i<len(lines) and (lines[i].startswith(' ') or lines[i].startswith('\t')):
                    t=lines[i].strip()
                    if t.startswith('-'):
                        arr.append(parse_scalar(t[1:].strip()))
                    elif ':' in t:
                        k,r=t.split(':',1); obj[k.strip()]=parse_scalar(r.strip())
                    i+=1
                root[key]=arr if arr else obj
        else:
            i+=1
    return root

def parse_toml(s):
    root=OrderedDict(); cur=root
    for ln in s.splitlines():
        ln=ln.strip()
        if not ln or ln.startswith('#'): continue
        if ln.startswith('[') and ln.endswith(']'):
            name=ln[1:-1].strip(); cur=root
            for part in name.split('.'):
                cur=cur.setdefault(part, OrderedDict())
        elif '=' in ln:
            k,v=ln.split('=',1); cur[k.strip()]=parse_scalar(v.strip())
    return root

# Output formatting

def clean_for_json(v):
    if isinstance(v, UndefinedType): return None
    if isinstance(v, J): return clean_for_json(v.v)
    if isinstance(v, OrderedDict): return {k: clean_for_json(val) for k,val in v.items()}
    if isinstance(v, dict): return {k: clean_for_json(val) for k,val in v.items()}
    if isinstance(v, list): return [clean_for_json(e) for e in v]
    return v

def atom(v):
    v=unwrap(v)
    if v is UNDEFINED: return 'undefined'
    if v is None: return 'null'
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v, str): return json.dumps(v, ensure_ascii=False)
    if isinstance(v, float):
        if math.isnan(v): return 'NaN'
        if math.isinf(v): return 'Infinity' if v>0 else '-Infinity'
        if v.is_integer(): return str(int(v))
    return str(v)

def is_scalar(v):
    v=unwrap(v); return not isinstance(v,(list,dict,OrderedDict))

def inline(v):
    v=unwrap(v)
    if isinstance(v, list): return '[ ' + ', '.join(format_value(e,0,False,False,'list_inline') for e in v) + ' ]'
    if isinstance(v, (dict,OrderedDict)): return '{ ' + ', '.join(json.dumps(str(k),ensure_ascii=False)+': '+format_value(val,0,False,False,'dict_inline') for k,val in v.items()) + ' }'
    return atom(v)

def format_value(v, indent=0, top=True, no_inline=False, context='top'):
    v=unwrap(v)
    if isinstance(v, (dict, OrderedDict)):
        items=list(v.items())
        if not top and not no_inline and context=='array' and all(is_scalar(val) for _,val in items):
            return inline(v)
        if not items: return '{}'
        sp=' ' * indent; child=' '*(indent+2)
        lines=['{']
        for idx,(k,val) in enumerate(items):
            comma=',' if idx<len(items)-1 else ''
            valctx='object'
            fv=format_value(val, indent+2, False, no_inline, valctx)
            lines.append(f'{child}{json.dumps(str(k), ensure_ascii=False)}: {fv}{comma}')
        lines.append(sp+'}')
        return '\n'.join(lines)
    if isinstance(v, list):
        if not top and not no_inline and all(is_scalar(e) for e in v): return inline(v)
        if not v: return '[]'
        sp=' '*indent; child=' '*(indent+2)
        lines=['[']
        for idx,e in enumerate(v):
            comma=',' if idx<len(v)-1 else ''
            fv=format_value(e, indent+2, False, no_inline, 'array')
            lines.append(f'{child}{fv}{comma}')
        lines.append(sp+']')
        return '\n'.join(lines)
    return atom(v)

def print_result(res, no_inline=False):
    v=unwrap(res)
    if v is UNDEFINED:
        sys.stderr.write('undefined\n'); return
    if isinstance(v, str):
        sys.stdout.write(v + '\n'); return
    sys.stdout.write(format_value(v, 0, True, no_inline) + '\n')

def print_error(expr, err):
    sys.stderr.write(f"\n  {expr}\n  {'^'*max(1,len(expr))}\n\n{err}\n")

