    for t in list(map(str, range(10))) + ['🔥','🔵','🟣','🥝']:
        sys.stdout.write(f'export FX_THEME="{t}"\n{THEME_SAMPLE}')

def completion(shell):
    if shell=='bash': print('complete -o filenames -C fx fx')
    elif shell=='fish': print("complete --command fx --arguments '(COMP_FISH=(commandline -cp) fx)'")
    elif shell=='zsh':
        print('''#compdef fx

