        fi
    fi
}

if [ "$funcstack[1]" = "_fx" ]; then
    _fx "$@"
else
    compdef _fx fx
fi''')
    else: print('unknown shell type')

def complete_env(kind):
    flags=['--help','--raw','--slurp','--themes','--version','--yaml','--toml','--strict','--no-inline']
    if kind=='zsh':
        for f in flags: sys.stdout.write(f'{f}\t{f}\tflag\n')
    else:
        for f in flags: sys.stdout.write(f+'\n')

def parse_args(argv):
    opts={'raw':False,'slurp':False,'yaml':False,'toml':False,'strict':False,'no_inline':False}
    codes=[]; i=0
    while i<len(argv):
        a=argv[i]
        if a in ('-h','--help'):
            sys.stdout.write(HELP); sys.exit(0)
        if a in ('-v','--version'):
            print(VERSION); sys.exit(0)
        if a=='--themes': print_themes(); sys.exit(0)
        if a.startswith('--comp='):
            completion(a.split('=',1)[1]); sys.exit(0)
        if a=='--comp':
            if i+1>=len(argv):
                sys.stderr.write('flag needs an argument: -comp\nUsage of ./executable:\n  -comp string\n    \t\n'); sys.exit(2)
            completion(argv[i+1]); sys.exit(0)
        if a in ('-r','--raw'): opts['raw']=True; i+=1; continue
        if a in ('-s','--slurp'): opts['slurp']=True; i+=1; continue
        # combined short flags like -sr
        if a.startswith('-') and not a.startswith('--') and len(a)>2:
            ok=True
            for ch in a[1:]:
                if ch=='s': opts['slurp']=True
                elif ch=='r': opts['raw']=True
                elif ch=='v': print(VERSION); sys.exit(0)
                elif ch=='h': sys.stdout.write(HELP); sys.exit(0)
                else: ok=False
            if ok: i+=1; continue
        if a=='--yaml': opts['yaml']=True; i+=1; continue
        if a=='--toml': opts['toml']=True; i+=1; continue
        if a=='--strict': opts['strict']=True; i+=1; continue
        if a=='--no-inline': opts['no_inline']=True; i+=1; continue
        if a=='--game-of-life': sys.exit(0)
        # Unknown flags in observed noninteractive mode are inert; keep non-flags as code.
        if a.startswith('-') and a not in ('-',):
            i+=1; continue
        codes.append(a); i+=1
    return opts,codes

def main():
    if os.environ.get('COMP_ZSH') is not None:
        complete_env('zsh'); return
    if os.environ.get('COMP_FISH') is not None:
        complete_env('fish'); return
    opts,codes=parse_args(sys.argv[1:])
    if not codes and len(sys.argv)==1:
        sys.stderr.write('panic: could not open a new TTY: open /dev/tty: no such device or address\n\ngoroutine 1 [running]:\nmain.main()\n\t/workspace/main.go:317 +0x191e\n')
        sys.exit(2)
    data=sys.stdin.read()
    if not data:
        return
    if not codes:
        sys.stderr.write('panic: could not open a new TTY: open /dev/tty: no such device or address\n\ngoroutine 1 [running]:\nmain.main()\n\t/workspace/main.go:317 +0x191e\n')
        sys.exit(2)
    try:
        if opts['raw']:
            vals=data.splitlines()
            if data and not vals: vals=['']
        elif opts['yaml']:
            vals=[parse_yaml(data)]
        elif opts['toml']:
            vals=[parse_toml(data)]
        else:
            vals=parse_json_values(data, opts['strict'])
    except Exception as e:
        sys.stderr.write(str(e)+'\n')
        sys.exit(1 if opts['strict'] else 0 if not codes else 1)
    if opts['slurp']:
        vals=[vals]
    exitcode=0
    for val in vals:
        cur=val
        try:
            for expr in codes:
                cur=eval_expr(expr, cur)
            print_result(cur, opts['no_inline'])
        except Exception as e:
            print_error(' '.join(codes), e)
            exitcode=1
            break
    sys.exit(exitcode)

if __name__=='__main__':
    main()
